(() => {
 const root=document.documentElement, hero=document.querySelector('#home'), nav=document.querySelector('.hero-navigation'), menu=nav.querySelector('nav');
 const reduced=matchMedia('(prefers-reduced-motion: reduce)');
 const wordmark=document.querySelector('.cell-heading>div');
 for(const corner of ['tl','tr','bl','br']){const el=document.createElement('span');el.className='hero-bracket '+corner;el.ariaHidden='true';wordmark.append(el);}
 const cue=document.createElement('a');cue.className='scroll-cue';cue.href='#about';cue.innerHTML='<span aria-hidden="true"></span> Scroll to explore';document.querySelector('.cell-form>div').append(cue);
 document.querySelectorAll('.section-label').forEach(label=>{const inner=document.createElement('div');inner.className='section-label-inner';while(label.firstChild)inner.append(label.firstChild);label.append(inner);});
 const links=[...menu.querySelectorAll('a')];links.forEach((a,i)=>{const number=document.createElement('span');number.className='nav-number';number.ariaHidden='true';number.textContent=String(i+1).padStart(2,'0');a.prepend(number);});
 const indicator=document.createElement('span');indicator.className='nav-indicator';indicator.ariaHidden='true';menu.append(indicator);
 function pointTo(link){if(!link){indicator.style.opacity=0;return;}indicator.style.opacity=1;indicator.style.transform=`translateX(${link.offsetLeft}px) scaleX(${link.offsetWidth})`;indicator.style.bottom=`${menu.offsetHeight-link.offsetTop-link.offsetHeight+3}px`;}
 const active=()=>pointTo(menu.querySelector('[aria-current]'));
 new MutationObserver(active).observe(menu,{subtree:true,attributes:true,attributeFilter:['aria-current']});
 links.forEach(a=>{a.addEventListener('pointerenter',()=>pointTo(a));a.addEventListener('focus',()=>pointTo(a));});menu.addEventListener('pointerleave',active);menu.addEventListener('focusout',()=>requestAnimationFrame(active));new ResizeObserver(active).observe(menu);
 const glyph='<svg class="theme-glyph" viewBox="0 0 24 24" aria-hidden="true" fill="none" stroke="currentColor" stroke-width="1.3"><g class="sun"><circle cx="12" cy="12" r="4"/><path d="M12 1v3m0 16v3M1 12h3m16 0h3M4 4l2 2m12 12 2 2M4 20l2-2M18 6l2-2"/></g><path class="moon" d="M20 15A9 9 0 0 1 9 4a8 8 0 1 0 11 11Z"/></svg>';
 const original=document.querySelector('#theme-toggle');original.insertAdjacentHTML('afterbegin',glyph);
 const tools=document.createElement('div');tools.className='nav-tools';tools.innerHTML=`<a class="nav-top" href="#home" aria-label="Back to top">↑</a>`;nav.append(tools);
 document.querySelectorAll('.stack-list>div p').forEach(p=>{const anchor=p.querySelector('a');const target=anchor||p;const text=target.textContent;const arrow=text.includes('↗');target.textContent='';const list=document.createElement('span');list.className='tech-items';for(const item of text.replace('↗','').split(' / ')){const span=document.createElement('span');span.textContent=item.trim();list.append(span);}target.append(list);if(arrow){const mark=document.createElement('span');mark.textContent='↗';mark.ariaHidden='true';target.append(mark);}});
 document.querySelectorAll('.project-links a').forEach(a=>{const path=a.href.includes('github.com')?'<path d="m8 5-6 7 6 7m8-14 6 7-6 7m-3-16-2 18"/>':'<rect x="3" y="3" width="18" height="18" rx="1"/><path d="M3 8h18M6 5.5h1m2 0h1"/>';a.insertAdjacentHTML('afterbegin',`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.3" aria-hidden="true">${path}</svg>`);});
 document.fonts.ready.then(()=>{const bounds=hero.getBoundingClientRect();const y=document.querySelector('.cell-label').getBoundingClientRect().bottom-bounds.top;if(!reduced.matches){for(const position of [y,document.querySelector('.cell-form').getBoundingClientRect().top-bounds.top]){const line=document.createElement('span');line.className='grid-draw horizontal';line.style.top=`${position-1}px`;hero.append(line);line.addEventListener('animationend',()=>line.remove(),{once:true});}const line=document.createElement('span');line.className='grid-draw vertical';hero.append(line);line.addEventListener('animationend',()=>line.remove(),{once:true});}active();});
})();
